window.marchStdlib = window.marchStdlib || {};
window.marchStdlib["session_theory.march"] = "-- Session.Theory: the logic of March's protocols, and laws about it.\n--\n-- A protocol (`protocol P do ... end`) is a global type: who sends what to\n-- whom, where a role chooses, where it loops.  Each role runs its\n-- projection, a local type.  The compiler projects twice, in OCaml (the\n-- `Chan(Role, Proto)` typechecker and the `@[endpoints]` generator); this\n-- module is the specification both are validated against\n-- (`march --check --guarantees`, lemmas design \u00a75.2, M6), and the laws below\n-- are proved once, here, for every protocol.\n--\n-- SessionRoles, labels and payload types are `Int` ids: the logic treats `String`\n-- contents as opaque, and the compiler maps names to ids when it emits a\n-- protocol as a `SessionGlobal`.\n--\n-- A loop is `GLoop(body, after)`.  The body's end is `GVar(0)`, the loop's\n-- own back-edge (de Bruijn: the nearest enclosing loop); `after` is what a\n-- role that takes no part in the body does next.  `stop` is `GEnd`.  A\n-- choice's branches each carry the rest of the protocol (the steps after the\n-- choice are appended to every branch).\nmod Session.Theory do\n\n  -- A global protocol over role, label and payload ids.\n  type SessionGlobal = GEnd\n              | GMsg(Int, Int, Int, SessionGlobal)\n              | GChoice(Int, SessionGBranches)\n              | GLoop(SessionGlobal, SessionGlobal)\n              | GVar(Int)\n\n  -- A choice's labelled branches.\n  type SessionGBranches = GBNil | GBCons(Int, SessionGlobal, SessionGBranches)\n\n  -- One role's view: send to or receive from a peer, choose or offer a label, loop.\n  type SessionLocal = LEnd\n             | LSend(Int, Int, SessionLocal)\n             | LRecv(Int, Int, SessionLocal)\n             | LChoose(SessionLBranches)\n             | LOffer(SessionLBranches)\n             | LRec(SessionLocal)\n             | LVar(Int)\n\n  -- A local choice's labelled branches.\n  type SessionLBranches = LBNil | LBCons(Int, SessionLocal, SessionLBranches)\n\n  derive Eq for SessionGlobal\n  derive Eq for SessionGBranches\n  derive Eq for SessionLocal\n  derive Eq for SessionLBranches\n\n  -- \u2500\u2500 duality \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"The other end of a conversation: every send a receive, every choice an offer.\"\n  fn dual(l : SessionLocal) : SessionLocal do\n    match l do\n      LEnd -> LEnd\n      LSend(p, t, k) -> LRecv(p, t, dual(k))\n      LRecv(p, t, k) -> LSend(p, t, dual(k))\n      LChoose(bs) -> LOffer(dual_bs(bs))\n      LOffer(bs) -> LChoose(dual_bs(bs))\n      LRec(k) -> LRec(dual(k))\n      LVar(i) -> LVar(i)\n    end\n  end\n\n  doc \"`dual` on every branch.\"\n  fn dual_bs(bs : SessionLBranches) : SessionLBranches do\n    match bs do\n      LBNil -> LBNil\n      LBCons(lab, k, rest) -> LBCons(lab, dual(k), dual_bs(rest))\n    end\n  end\n\n  doc \"`l` with every peer replaced by 0: a two-party conversation, where the peer is implied.\"\n  fn erase(l : SessionLocal) : SessionLocal do\n    match l do\n      LEnd -> LEnd\n      LSend(_, t, k) -> LSend(0, t, erase(k))\n      LRecv(_, t, k) -> LRecv(0, t, erase(k))\n      LChoose(bs) -> LChoose(erase_bs(bs))\n      LOffer(bs) -> LOffer(erase_bs(bs))\n      LRec(k) -> LRec(erase(k))\n      LVar(i) -> LVar(i)\n    end\n  end\n\n  doc \"`erase` on every branch.\"\n  fn erase_bs(bs : SessionLBranches) : SessionLBranches do\n    match bs do\n      LBNil -> LBNil\n      LBCons(lab, k, rest) -> LBCons(lab, erase(k), erase_bs(rest))\n    end\n  end\n\n  -- \u2500\u2500 projection \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"Structural equality of local types, written out so the logic can use it (a derived `Eq` on a recursive type is not yet reflected).\"\n  fn same(a : SessionLocal, b : SessionLocal) : Bool do\n    match a do\n      LEnd -> match b do\n        LEnd -> true\n        _ -> false\n      end\n      LSend(p, t, k) -> match b do\n        LSend(q, u, j) -> p == q && t == u && same(k, j)\n        _ -> false\n      end\n      LRecv(p, t, k) -> match b do\n        LRecv(q, u, j) -> p == q && t == u && same(k, j)\n        _ -> false\n      end\n      LChoose(xs) -> match b do\n        LChoose(ys) -> same_bs(xs, ys)\n        _ -> false\n      end\n      LOffer(xs) -> match b do\n        LOffer(ys) -> same_bs(xs, ys)\n        _ -> false\n      end\n      LRec(k) -> match b do\n        LRec(j) -> same(k, j)\n        _ -> false\n      end\n      LVar(i) -> match b do\n        LVar(j) -> i == j\n        _ -> false\n      end\n    end\n  end\n\n  doc \"`same` on branch lists.\"\n  fn same_bs(xs : SessionLBranches, ys : SessionLBranches) : Bool do\n    match xs do\n      LBNil -> match ys do\n        LBNil -> true\n        _ -> false\n      end\n      LBCons(l, k, rest) -> match ys do\n        LBCons(m, j, more) -> l == m && same(k, j) && same_bs(rest, more)\n        _ -> false\n      end\n    end\n  end\n\n  doc \"Whether every branch is `l`.\"\n  fn all_same(bs : SessionLBranches, l : SessionLocal) : Bool do\n    match bs do\n      LBNil -> true\n      LBCons(_, k, rest) -> same(k, l) && all_same(rest, l)\n    end\n  end\n\n  doc \"A role that does not choose sees the branches merged: in a multiparty protocol, one branch when every branch is the same (it never learns the label), else an offer.\"\n  fn merge(bs : SessionLBranches, multiparty : Bool) : SessionLocal do\n    match bs do\n      LBNil -> LOffer(LBNil)\n      LBCons(_, first, rest) ->\n        if multiparty && all_same(rest, first) do first else LOffer(bs) end\n    end\n  end\n\n  doc \"A loop's projection: no loop at all when the role takes no part in the body.\"\n  fn loop_of(body : SessionLocal, after : SessionLocal) : SessionLocal do\n    match body do\n      LVar(_) -> after\n      LEnd -> LRec(body)\n      LSend(_, _, _) -> LRec(body)\n      LRecv(_, _, _) -> LRec(body)\n      LChoose(_) -> LRec(body)\n      LOffer(_) -> LRec(body)\n      LRec(_) -> LRec(body)\n    end\n  end\n\n  doc \"Role `r`'s projection of `g`.  `multiparty` is true for more than two roles: only then may a non-chooser merge a choice's branches.\"\n  fn project(g : SessionGlobal, r : Int, multiparty : Bool) : SessionLocal do\n    match g do\n      GEnd -> LEnd\n      GVar(i) -> LVar(i)\n      GMsg(from, to, t, k) ->\n        if from == r do LSend(to, t, project(k, r, multiparty))\n        else if to == r do LRecv(from, t, project(k, r, multiparty))\n        else project(k, r, multiparty) end end\n      GChoice(c, bs) ->\n        if c == r do LChoose(project_bs(bs, r, multiparty))\n        else merge(project_bs(bs, r, multiparty), multiparty) end\n      GLoop(body, after) -> loop_of(project(body, r, multiparty), project(after, r, multiparty))\n    end\n  end\n\n  doc \"`project` on every branch.\"\n  fn project_bs(bs : SessionGBranches, r : Int, multiparty : Bool) : SessionLBranches do\n    match bs do\n      GBNil -> LBNil\n      GBCons(lab, k, rest) -> LBCons(lab, project(k, r, multiparty), project_bs(rest, r, multiparty))\n    end\n  end\n\n  doc \"Every branch begins with a receive from `c`.\"\n  fn heads_from(bs : SessionLBranches, c : Int) : Bool do\n    match bs do\n      LBNil -> true\n      LBCons(_, k, rest) ->\n        match k do\n          LRecv(p, _, _) -> p == c && heads_from(rest, c)\n          _ -> false\n        end\n    end\n  end\n\n  doc \"A role that does not choose is told the choice: its branches are all the same, or each begins with the chooser's message.\"\n  fn told(bs : SessionLBranches, c : Int) : Bool do\n    match bs do\n      LBNil -> true\n      LBCons(_, first, rest) -> all_same(rest, first) || heads_from(bs, c)\n    end\n  end\n\n  doc \"Role `r` learns every choice it must: in a multiparty protocol, a role whose branches differ receives the chooser's message first (a two-party offer is told by the label).\"\n  fn informed(g : SessionGlobal, r : Int, multiparty : Bool) : Bool do\n    match g do\n      GEnd -> true\n      GVar(_) -> true\n      GMsg(_, _, _, k) -> informed(k, r, multiparty)\n      GChoice(c, bs) ->\n        (c == r || !multiparty || told(project_bs(bs, r, multiparty), c)) && informed_bs(bs, r, multiparty)\n      GLoop(body, after) -> informed(body, r, multiparty) && informed(after, r, multiparty)\n    end\n  end\n\n  doc \"`informed` on every branch.\"\n  fn informed_bs(bs : SessionGBranches, r : Int, multiparty : Bool) : Bool do\n    match bs do\n      GBNil -> true\n      GBCons(_, k, rest) -> informed(k, r, multiparty) && informed_bs(rest, r, multiparty)\n    end\n  end\n\n  doc \"Role `x`'s part of `l`: the actions with peer `x`, peers erased (two parties, so the peer is implied), and a choice whose branches then all look alike is no choice.\"\n  fn restrict(l : SessionLocal, x : Int) : SessionLocal do\n    match l do\n      LEnd -> LEnd\n      LSend(p, t, k) -> if p == x do LSend(0, t, restrict(k, x)) else restrict(k, x) end\n      LRecv(p, t, k) -> if p == x do LRecv(0, t, restrict(k, x)) else restrict(k, x) end\n      LChoose(bs) -> collapse(restrict_bs(bs, x), true)\n      LOffer(bs) -> collapse(restrict_bs(bs, x), false)\n      LRec(k) -> LRec(restrict(k, x))\n      LVar(i) -> LVar(i)\n    end\n  end\n\n  doc \"`restrict` on every branch.\"\n  fn restrict_bs(bs : SessionLBranches, x : Int) : SessionLBranches do\n    match bs do\n      LBNil -> LBNil\n      LBCons(lab, k, rest) -> LBCons(lab, restrict(k, x), restrict_bs(rest, x))\n    end\n  end\n\n  doc \"Restricted branches: one branch when all look alike, else a choice (`as_choice`) or an offer.\"\n  fn collapse(rb : SessionLBranches, as_choice : Bool) : SessionLocal do\n    match rb do\n      LBNil -> if as_choice do LChoose(LBNil) else LOffer(LBNil) end\n      LBCons(_, first, rest) ->\n        if all_same(rest, first) do first\n        else if as_choice do LChoose(rb) else LOffer(rb) end end\n    end\n  end\n\n  -- \u2500\u2500 which protocols \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"Every message and choice of `g` is between roles `a` and `b`.\"\n  fn binary(g : SessionGlobal, a : Int, b : Int) : Bool do\n    match g do\n      GEnd -> true\n      GVar(_) -> true\n      GMsg(from, to, _, k) ->\n        ((from == a && to == b) || (from == b && to == a)) && binary(k, a, b)\n      GChoice(c, bs) -> (c == a || c == b) && binary_bs(bs, a, b)\n      GLoop(body, after) -> binary(body, a, b) && binary(after, a, b)\n    end\n  end\n\n  doc \"`binary` on every branch.\"\n  fn binary_bs(bs : SessionGBranches, a : Int, b : Int) : Bool do\n    match bs do\n      GBNil -> true\n      GBCons(_, k, rest) -> binary(k, a, b) && binary_bs(rest, a, b)\n    end\n  end\n\n  -- \u2500\u2500 laws \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"C1. Duality is an involution.\"\n  @[lemma]\n  fn dual_dual(l : SessionLocal) : {Unit | dual(dual(l)) == l} do\n    match l do\n      LEnd -> ()\n      LSend(_, _, k) -> dual_dual(k)\n      LRecv(_, _, k) -> dual_dual(k)\n      LChoose(bs) -> dual_dual_bs(bs)\n      LOffer(bs) -> dual_dual_bs(bs)\n      LRec(k) -> dual_dual(k)\n      LVar(_) -> ()\n    end\n  end\n\n  doc \"C1 on every branch.\"\n  @[lemma]\n  fn dual_dual_bs(bs : SessionLBranches) : {Unit | dual_bs(dual_bs(bs)) == bs} do\n    match bs do\n      LBNil -> ()\n      LBCons(_, k, rest) ->\n        dual_dual(k)\n        dual_dual_bs(rest)\n    end\n  end\n\n  doc \"Duality commutes with leaving out a loop no one takes part in.\"\n  @[lemma]\n  fn dual_loop_of(body : SessionLocal, after : SessionLocal)\n    : {Unit | dual(loop_of(body, after)) == loop_of(dual(body), dual(after))} do\n    match body do\n      LVar(_) -> ()\n      LEnd -> ()\n      LSend(_, _, _) -> ()\n      LRecv(_, _, _) -> ()\n      LChoose(_) -> ()\n      LOffer(_) -> ()\n      LRec(_) -> ()\n    end\n  end\n\n  doc \"`same` is structural equality.\"\n  @[lemma]\n  fn same_eq(a : SessionLocal, b : SessionLocal) : {Unit | same(a, b) == (a == b)} do\n    match a do\n      LEnd -> ()\n      LSend(_, _, k) -> match b do\n        LSend(_, _, j) -> same_eq(k, j)\n        _ -> ()\n      end\n      LRecv(_, _, k) -> match b do\n        LRecv(_, _, j) -> same_eq(k, j)\n        _ -> ()\n      end\n      LChoose(xs) -> match b do\n        LChoose(ys) -> same_eq_bs(xs, ys)\n        _ -> ()\n      end\n      LOffer(xs) -> match b do\n        LOffer(ys) -> same_eq_bs(xs, ys)\n        _ -> ()\n      end\n      LRec(k) -> match b do\n        LRec(j) -> same_eq(k, j)\n        _ -> ()\n      end\n      LVar(_) -> ()\n    end\n  end\n\n  doc \"`same_bs` is structural equality.\"\n  @[lemma]\n  fn same_eq_bs(xs : SessionLBranches, ys : SessionLBranches) : {Unit | same_bs(xs, ys) == (xs == ys)} do\n    match xs do\n      LBNil -> ()\n      LBCons(_, k, rest) -> match ys do\n        LBCons(_, j, more) ->\n          same_eq(k, j)\n          same_eq_bs(rest, more)\n        _ -> ()\n      end\n    end\n  end\n\n  doc \"Erasing peers commutes with leaving out a loop no one takes part in.\"\n  @[lemma]\n  fn erase_loop_of(body : SessionLocal, after : SessionLocal)\n    : {Unit | erase(loop_of(body, after)) == loop_of(erase(body), erase(after))} do\n    match body do\n      LVar(_) -> ()\n      LEnd -> ()\n      LSend(_, _, _) -> ()\n      LRecv(_, _, _) -> ()\n      LChoose(_) -> ()\n      LOffer(_) -> ()\n      LRec(_) -> ()\n    end\n  end\n\n  doc \"In a binary protocol a choice is always offered, never merged.\"\n  @[lemma]\n  fn merge_binary(bs : SessionLBranches) : {Unit | merge(bs, false) == LOffer(bs)} do\n    match bs do\n      LBNil -> ()\n      LBCons(_, _, _) -> ()\n    end\n  end\n\n  doc \"C2. A binary protocol's two projections are dual (peers erased: each has one).\"\n  @[lemma]\n  fn project_dual(a : Int, b : {Int | _ != a}, g : SessionGlobal)\n    : {Unit | !binary(g, a, b) || erase(project(g, b, false)) == dual(erase(project(g, a, false)))} do\n    match g do\n      GEnd -> ()\n      GVar(_) -> ()\n      GMsg(_, _, _, k) -> project_dual(a, b, k)\n      GChoice(_, bs) ->\n        project_dual_bs(a, b, bs)\n        let pa = project_bs(bs, a, false)\n        let pb = project_bs(bs, b, false)\n        merge_binary(pa)\n        merge_binary(pb)\n      GLoop(body, after) ->\n        project_dual(a, b, body)\n        project_dual(a, b, after)\n        let ba = project(body, a, false)\n        let aa = project(after, a, false)\n        let bb = project(body, b, false)\n        let ab = project(after, b, false)\n        erase_loop_of(ba, aa)\n        erase_loop_of(bb, ab)\n        let eba = erase(ba)\n        let eaa = erase(aa)\n        dual_loop_of(eba, eaa)\n    end\n  end\n\n  doc \"C2 on every branch.\"\n  @[lemma]\n  fn project_dual_bs(a : Int, b : {Int | _ != a}, bs : SessionGBranches)\n    : {Unit | !binary_bs(bs, a, b) || erase_bs(project_bs(bs, b, false)) == dual_bs(erase_bs(project_bs(bs, a, false)))} do\n    match bs do\n      GBNil -> ()\n      GBCons(_, k, rest) ->\n        project_dual(a, b, k)\n        project_dual_bs(a, b, rest)\n    end\n  end\n\n  -- \u2500\u2500 the fragment C3-C5 cover \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- The roles of a configuration (its own list type: see Session.Theory's\n  -- progress note on a reflected function over the stdlib List).\n  type SessionRoles = RoleEnd | RoleThen(Int, SessionRoles)\n\n  --\n  -- Loop-free (`stop` is GEnd), crash-free, and every choice DIRECTED: each\n  -- branch begins with the chooser's message to one receiver, and every\n  -- other role's branches project alike (it never needs the label).  The\n  -- semantics is synchronous: a message is one step of sender and receiver\n  -- together (choreography.md \"Message order\").\n\n  doc \"Whether `r` is in the role list.\"\n  fn has(rs : SessionRoles, r : Int) : Bool do\n    match rs do\n      RoleEnd -> false\n      RoleThen(x, rest) -> x == r || has(rest, r)\n    end\n  end\n\n  doc \"The receiver of a choice's first branch head (-1 when there is none).\"\n  fn dest(bs : SessionGBranches) : Int do\n    match bs do\n      GBCons(_, g, _) ->\n        match g do\n          GMsg(_, t, _, _) -> t\n          _ -> 0 - 1\n        end\n      GBNil -> 0 - 1\n    end\n  end\n\n  doc \"Every branch begins with a message from `c` to `t`.\"\n  fn directed(bs : SessionGBranches, c : Int, t : Int) : Bool do\n    match bs do\n      GBNil -> true\n      GBCons(_, g, rest) ->\n        match g do\n          GMsg(f, to, _, _) -> f == c && to == t && directed(rest, c, t)\n          _ -> false\n        end\n    end\n  end\n\n  doc \"A non-empty branch list whose branches all project alike.\"\n  fn merged(pbs : SessionLBranches) : Bool do\n    match pbs do\n      LBNil -> false\n      LBCons(_, first, rest) -> all_same(rest, first)\n    end\n  end\n\n  doc \"Role `r` takes part in choice `bs` by `c` correctly: it is the chooser, the receiver of every branch head, or its branches project alike.\"\n  fn role_ok(c : Int, bs : SessionGBranches, r : Int, multiparty : Bool) : Bool do\n    r == c || r == dest(bs) || (multiparty && merged(project_bs(bs, r, multiparty)))\n  end\n\n  doc \"`role_ok` for every role of `rs`.\"\n  fn bystanders_merged(rs : SessionRoles, c : Int, bs : SessionGBranches, multiparty : Bool) : Bool do\n    match rs do\n      RoleEnd -> true\n      RoleThen(r, rest) -> role_ok(c, bs, r, multiparty) && bystanders_merged(rest, c, bs, multiparty)\n    end\n  end\n\n  doc \"Whether a choice has any branch.\"\n  fn nonempty(bs : SessionGBranches) : Bool do\n    match bs do\n      GBNil -> false\n      GBCons(_, _, _) -> true\n    end\n  end\n\n  doc \"A directed choice: branches, each beginning with a message from `c` to one other role.\"\n  fn choice_ok(c : Int, bs : SessionGBranches) : Bool do\n    nonempty(bs) && dest(bs) != c && directed(bs, c, dest(bs))\n  end\n\n  doc \"`g` is in the fragment C3-C5 cover, over the roles `rs`: loop-free, every message between two different roles of `rs`, every choice directed with its bystanders merged.\"\n  fn in_fragment(g : SessionGlobal, rs : SessionRoles, multiparty : Bool) : Bool do\n    match g do\n      GEnd -> true\n      GVar(_) -> false\n      GLoop(_, _) -> false\n      GMsg(f, t, _, k) -> f != t && has(rs, f) && has(rs, t) && in_fragment(k, rs, multiparty)\n      GChoice(c, bs) ->\n        choice_ok(c, bs) && has(rs, c) && has(rs, dest(bs))\n          && bystanders_merged(rs, c, bs, multiparty) && in_fragment_bs(bs, rs, multiparty)\n    end\n  end\n\n  doc \"`in_fragment` on every branch.\"\n  fn in_fragment_bs(bs : SessionGBranches, rs : SessionRoles, multiparty : Bool) : Bool do\n    match bs do\n      GBNil -> true\n      GBCons(_, g, rest) -> in_fragment(g, rs, multiparty) && in_fragment_bs(rest, rs, multiparty)\n    end\n  end\n\n  -- \u2500\u2500 configurations and steps \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- A sequence of steps.\n  type SessionActs = ActEnd | ActThen(SessionAct, SessionActs)\n\n  -- The labels to take at successive choices.\n  type SessionPicks = PickEnd | PickThen(Int, SessionPicks)\n\n  -- One step of the whole system: a message, or a choice whose label rides\n  -- on the chooser's first message (chooser, receiver, label, payload).\n  type SessionAct = ActMsg(Int, Int, Int) | ActPick(Int, Int, Int, Int)\n\n  -- Every role with its local type.\n  type SessionCfg = CfgEnd | CfgRole(Int, SessionLocal, SessionCfg)\n\n  -- The result of a step.\n  type SessionCfgStep = CfgStuck | CfgMoved(SessionCfg)\n\n  -- One role's part of a step.\n  type SessionLStep = StepBad | StepOk(SessionLocal)\n\n  derive Eq for SessionAct\n  derive Eq for SessionActs\n  derive Eq for SessionPicks\n  derive Eq for SessionCfg\n  derive Eq for SessionCfgStep\n  derive Eq for SessionLStep\n\n  doc \"The configuration of `g`: every role of `rs` runs its projection.\"\n  fn config(g : SessionGlobal, rs : SessionRoles, multiparty : Bool) : SessionCfg do\n    match rs do\n      RoleEnd -> CfgEnd\n      RoleThen(r, rest) -> CfgRole(r, project(g, r, multiparty), config(g, rest, multiparty))\n    end\n  end\n\n  doc \"Whether role `r` is in the configuration.\"\n  fn present(cfg : SessionCfg, r : Int) : Bool do\n    match cfg do\n      CfgEnd -> false\n      CfgRole(x, _, rest) -> x == r || present(rest, r)\n    end\n  end\n\n  doc \"Send `p` to `t`, if that is what `l` does next.\"\n  fn send_step(l : SessionLocal, t : Int, p : Int) : SessionLStep do\n    match l do\n      LSend(x, y, k) -> if x == t && y == p do StepOk(k) else StepBad end\n      _ -> StepBad\n    end\n  end\n\n  doc \"Receive `p` from `f`, if that is what `l` does next.\"\n  fn recv_step(l : SessionLocal, f : Int, p : Int) : SessionLStep do\n    match l do\n      LRecv(x, y, k) -> if x == f && y == p do StepOk(k) else StepBad end\n      _ -> StepBad\n    end\n  end\n\n  doc \"The first branch labelled `lab`.\"\n  fn find(bs : SessionLBranches, lab : Int) : SessionLStep do\n    match bs do\n      LBNil -> StepBad\n      LBCons(l, k, rest) -> if l == lab do StepOk(k) else find(rest, lab) end\n    end\n  end\n\n  doc \"Choose `lab` and send its first message.\"\n  @[reflect(fuel: 4)]\n  fn choose_step(l : SessionLocal, lab : Int, t : Int, p : Int) : SessionLStep do\n    match l do\n      LChoose(bs) ->\n        match find(bs, lab) do\n          StepOk(k) -> send_step(k, t, p)\n          StepBad -> StepBad\n        end\n      _ -> StepBad\n    end\n  end\n\n  doc \"Receive the chooser's first message of branch `lab`: from an offer, or from a merged receive.\"\n  @[reflect(fuel: 4)]\n  fn offer_step(l : SessionLocal, lab : Int, c : Int, p : Int) : SessionLStep do\n    match l do\n      LOffer(bs) ->\n        match find(bs, lab) do\n          StepOk(k) -> recv_step(k, c, p)\n          StepBad -> StepBad\n        end\n      LRecv(_, _, _) -> recv_step(l, c, p)\n      _ -> StepBad\n    end\n  end\n\n  doc \"Role `r`'s part in step `a`; a role not in it stays as it is.\"\n  @[reflect(fuel: 4)]\n  fn act(r : Int, l : SessionLocal, a : SessionAct) : SessionLStep do\n    match a do\n      ActMsg(f, t, p) ->\n        if r == f do send_step(l, t, p) else if r == t do recv_step(l, f, p) else StepOk(l) end end\n      ActPick(c, t, lab, p) ->\n        if r == c do choose_step(l, lab, t, p) else if r == t do offer_step(l, lab, c, p) else StepOk(l) end end\n    end\n  end\n\n  doc \"Every role takes its part in `a`.\"\n  fn apply(cfg : SessionCfg, a : SessionAct) : SessionCfgStep do\n    match cfg do\n      CfgEnd -> CfgMoved(CfgEnd)\n      CfgRole(r, l, rest) ->\n        match act(r, l, a) do\n          StepBad -> CfgStuck\n          StepOk(l2) ->\n            match apply(rest, a) do\n              CfgStuck -> CfgStuck\n              CfgMoved(c2) -> CfgMoved(CfgRole(r, l2, c2))\n            end\n        end\n    end\n  end\n\n  doc \"The sender of `a`.\"\n  fn act_from(a : SessionAct) : Int do\n    match a do\n      ActMsg(f, _, _) -> f\n      ActPick(c, _, _, _) -> c\n    end\n  end\n\n  doc \"The receiver of `a`.\"\n  fn act_to(a : SessionAct) : Int do\n    match a do\n      ActMsg(_, t, _) -> t\n      ActPick(_, t, _, _) -> t\n    end\n  end\n\n  doc \"One synchronous step: both parties are there and each can take its part.\"\n  fn step(cfg : SessionCfg, a : SessionAct) : SessionCfgStep do\n    if present(cfg, act_from(a)) && present(cfg, act_to(a)) do apply(cfg, a) else CfgStuck end\n  end\n\n  doc \"Run the steps in order.\"\n  fn run(cfg : SessionCfg, acts : SessionActs) : SessionCfgStep do\n    match acts do\n      ActEnd -> CfgMoved(cfg)\n      ActThen(a, rest) ->\n        match step(cfg, a) do\n          CfgStuck -> CfgStuck\n          CfgMoved(c2) -> run(c2, rest)\n        end\n    end\n  end\n\n  -- \u2500\u2500 the protocol's own run \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"Whether some branch is labelled `lab`.\"\n  fn has_label(bs : SessionGBranches, lab : Int) : Bool do\n    match bs do\n      GBNil -> false\n      GBCons(l, _, rest) -> l == lab || has_label(rest, lab)\n    end\n  end\n\n  doc \"The first branch's label.\"\n  fn first_label(bs : SessionGBranches) : Int do\n    match bs do\n      GBNil -> 0\n      GBCons(l, _, _) -> l\n    end\n  end\n\n  doc \"The first branch labelled `lab` (GEnd when there is none).\"\n  @[reflect(fuel: 4)]\n  fn gbranch(bs : SessionGBranches, lab : Int) : SessionGlobal do\n    match bs do\n      GBNil -> GEnd\n      GBCons(l, g, rest) -> if l == lab do g else gbranch(rest, lab) end\n    end\n  end\n\n  doc \"The payload of branch `lab`'s first message.\"\n  fn gpay(bs : SessionGBranches, lab : Int) : Int do\n    match bs do\n      GBNil -> 0\n      GBCons(l, g, rest) ->\n        if l == lab do\n          match g do\n            GMsg(_, _, p, _) -> p\n            _ -> 0\n          end\n        else gpay(rest, lab) end\n    end\n  end\n\n  doc \"What follows branch `lab`'s first message.\"\n  fn gcont(bs : SessionGBranches, lab : Int) : SessionGlobal do\n    match bs do\n      GBNil -> GEnd\n      GBCons(l, g, rest) ->\n        if l == lab do\n          match g do\n            GMsg(_, _, _, k) -> k\n            _ -> GEnd\n          end\n        else gcont(rest, lab) end\n    end\n  end\n\n  doc \"The first branch's local type (LEnd when there is none).\"\n  fn lhead(bs : SessionLBranches) : SessionLocal do\n    match bs do\n      LBNil -> LEnd\n      LBCons(_, k, _) -> k\n    end\n  end\n\n  doc \"The label `picks` asks for, when there is such a branch; else the first.\"\n  fn pick(bs : SessionGBranches, picks : SessionPicks) : Int do\n    match picks do\n      PickEnd -> first_label(bs)\n      PickThen(l, _) -> if has_label(bs, l) do l else first_label(bs) end\n    end\n  end\n\n  doc \"The rest of `picks` after one choice.\"\n  fn rest_picks(picks : SessionPicks) : SessionPicks do\n    match picks do\n      PickEnd -> PickEnd\n      PickThen(_, rest) -> rest\n    end\n  end\n\n  doc \"The steps of `g` when each choice takes the label `picks` lists in turn (loop-free).\"\n  fn trace(g : SessionGlobal, picks : SessionPicks) : SessionActs do\n    match g do\n      GEnd -> ActEnd\n      GVar(_) -> ActEnd\n      GLoop(_, _) -> ActEnd\n      GMsg(f, t, p, k) -> ActThen(ActMsg(f, t, p), trace(k, picks))\n      GChoice(c, bs) -> trace_bs(bs, c, dest(bs), pick(bs, picks), rest_picks(picks))\n    end\n  end\n\n  doc \"The steps of branch `lab`: the chooser's first message carries the label.\"\n  fn trace_bs(bs : SessionGBranches, c : Int, t : Int, lab : Int, picks : SessionPicks) : SessionActs do\n    match bs do\n      GBNil -> ActEnd\n      GBCons(l, g, rest) ->\n        if l == lab do\n          match g do\n            GMsg(_, _, p, k) -> ActThen(ActPick(c, t, lab, p), trace(k, picks))\n            _ -> ActEnd\n          end\n        else trace_bs(rest, c, t, lab, picks) end\n    end\n  end\n\n  -- \u2500\u2500 C4 and C5: the projections run the protocol \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"A configuration has exactly the roles it was built from.\"\n  @[lemma]\n  fn present_config(g : SessionGlobal, rs : SessionRoles, multiparty : Bool, r : Int)\n    : {Unit | present(config(g, rs, multiparty), r) == has(rs, r)} do\n    match rs do\n      RoleEnd -> ()\n      RoleThen(_, rest) -> present_config(g, rest, multiparty, r)\n    end\n  end\n\n  doc \"One role's part in a message step: it ends at its projection of what follows.\"\n  @[lemma]\n  fn act_msg(f : Int, t : {Int | _ != f}, p : Int, k : SessionGlobal, r : Int, multiparty : Bool)\n    : {Unit | act(r, project(GMsg(f, t, p, k), r, multiparty), ActMsg(f, t, p)) == StepOk(project(k, r, multiparty))} do\n    let rest = project(k, r, multiparty)\n    if r == f do\n      assert project(GMsg(f, t, p, k), r, multiparty) == LSend(t, p, rest)\n      assert send_step(LSend(t, p, rest), t, p) == StepOk(rest)\n    else if r == t do\n      assert project(GMsg(f, t, p, k), r, multiparty) == LRecv(f, p, rest)\n      assert recv_step(LRecv(f, p, rest), f, p) == StepOk(rest)\n    else\n      assert project(GMsg(f, t, p, k), r, multiparty) == rest\n    end end\n  end\n\n  doc \"Every role takes its part in a message step.\"\n  @[lemma]\n  fn apply_msg(f : Int, t : {Int | _ != f}, p : Int, k : SessionGlobal, rs : SessionRoles, multiparty : Bool)\n    : {Unit | apply(config(GMsg(f, t, p, k), rs, multiparty), ActMsg(f, t, p)) == CfgMoved(config(k, rs, multiparty))} do\n    match rs do\n      RoleEnd -> ()\n      RoleThen(r, rest) ->\n        act_msg(f, t, p, k, r, multiparty)\n        apply_msg(f, t, p, k, rest, multiparty)\n    end\n  end\n\n  doc \"Subject reduction for a message: its step takes the configuration of `GMsg(f, t, p, k)` to that of `k`.\"\n  @[lemma]\n  fn step_msg(f : Int, t : {Int | _ != f}, p : Int, k : SessionGlobal, rs : SessionRoles, multiparty : Bool)\n    : {Unit | !(has(rs, f) && has(rs, t)) || step(config(GMsg(f, t, p, k), rs, multiparty), ActMsg(f, t, p)) == CfgMoved(config(k, rs, multiparty))} do\n    present_config(GMsg(f, t, p, k), rs, multiparty, f)\n    present_config(GMsg(f, t, p, k), rs, multiparty, t)\n    apply_msg(f, t, p, k, rs, multiparty)\n    assert act_from(ActMsg(f, t, p)) == f\n    assert act_to(ActMsg(f, t, p)) == t\n  end\n\n  doc \"Looking up a label in a projected choice gives the projection of that branch.\"\n  @[lemma]\n  fn find_project(bs : SessionGBranches, r : Int, multiparty : Bool, lab : Int)\n    : {Unit | !has_label(bs, lab) || find(project_bs(bs, r, multiparty), lab) == StepOk(project(gbranch(bs, lab), r, multiparty))} do\n    match bs do\n      GBNil -> ()\n      GBCons(_, _, rest) -> find_project(rest, r, multiparty, lab)\n    end\n  end\n\n  doc \"In branches that are all `first`, a lookup finds `first` or nothing.\"\n  @[lemma]\n  fn find_all_same(rest : SessionLBranches, first : SessionLocal, lab : Int)\n    : {Unit | !all_same(rest, first) || find(rest, lab) == StepBad || find(rest, lab) == StepOk(first)} do\n    match rest do\n      LBNil -> ()\n      LBCons(_, k, more) ->\n        same_eq(k, first)\n        find_all_same(more, first, lab)\n    end\n  end\n\n  doc \"In merged branches, a lookup finds the first branch or nothing.\"\n  @[lemma]\n  fn find_merged(pbs : SessionLBranches, lab : Int)\n    : {Unit | !merged(pbs) || find(pbs, lab) == StepBad || find(pbs, lab) == StepOk(lhead(pbs))} do\n    match pbs do\n      LBNil -> ()\n      LBCons(_, first, rest) -> find_all_same(rest, first, lab)\n    end\n  end\n\n  doc \"How a non-chooser sees a choice: merged into its first branch, or an offer.\"\n  @[lemma]\n  fn merge_cases(pbs : SessionLBranches, multiparty : Bool)\n    : {Unit | !merged(pbs) && !multiparty && merge(pbs, multiparty) == LOffer(pbs)\n              || (multiparty && merged(pbs) && merge(pbs, multiparty) == lhead(pbs))\n              || (!(multiparty && merged(pbs)) && merge(pbs, multiparty) == LOffer(pbs))} do\n    match pbs do\n      LBNil -> ()\n      LBCons(_, _, _) -> ()\n    end\n  end\n\n  doc \"In a directed choice, branch `lab` is the chooser's message to the receiver.\"\n  @[lemma]\n  fn directed_branch(bs : SessionGBranches, c : Int, t : Int, lab : Int)\n    : {Unit | !(directed(bs, c, t) && has_label(bs, lab)) || gbranch(bs, lab) == GMsg(c, t, gpay(bs, lab), gcont(bs, lab))} do\n    match bs do\n      GBNil -> ()\n      GBCons(_, _, rest) -> directed_branch(rest, c, t, lab)\n    end\n  end\n\n  doc \"One role's part in a choice step: it ends at its projection of what follows branch `lab`'s first message.\"\n  @[lemma]\n  fn act_pick(c : Int, bs : SessionGBranches, multiparty : Bool, lab : Int, r : Int)\n    : {Unit | !(choice_ok(c, bs) && role_ok(c, bs, r, multiparty) && has_label(bs, lab))\n              || act(r, project(GChoice(c, bs), r, multiparty), ActPick(c, dest(bs), lab, gpay(bs, lab)))\n                 == StepOk(project(gcont(bs, lab), r, multiparty))} do\n    if choice_ok(c, bs) && role_ok(c, bs, r, multiparty) && has_label(bs, lab) do\n      let t = dest(bs)\n      let p = gpay(bs, lab)\n      let k = gcont(bs, lab)\n      let pbs = project_bs(bs, r, multiparty)\n      let after = project(k, r, multiparty)\n      assert directed(bs, c, t)\n      find_project(bs, r, multiparty, lab)\n      directed_branch(bs, c, t, lab)\n      let g = gbranch(bs, lab)\n      assert g == GMsg(c, t, p, k)\n      assert find(pbs, lab) == StepOk(project(g, r, multiparty))\n      assert find(pbs, lab) == StepOk(project(GMsg(c, t, p, k), r, multiparty))\n      if r == c do\n        assert project(GChoice(c, bs), r, multiparty) == LChoose(pbs)\n        assert project(GMsg(c, t, p, k), r, multiparty) == LSend(t, p, after)\n        assert find(pbs, lab) == StepOk(LSend(t, p, after))\n        assert send_step(LSend(t, p, after), t, p) == StepOk(after)\n        assert choose_step(LChoose(pbs), lab, t, p) == StepOk(after)\n        assert act(r, LChoose(pbs), ActPick(c, t, lab, p)) == StepOk(after)\n      else\n        assert project(GChoice(c, bs), r, multiparty) == merge(pbs, multiparty)\n        merge_cases(pbs, multiparty)\n        find_merged(pbs, lab)\n        if r == t do\n          assert project(GMsg(c, t, p, k), r, multiparty) == LRecv(c, p, after)\n          assert find(pbs, lab) == StepOk(LRecv(c, p, after))\n          assert recv_step(LRecv(c, p, after), c, p) == StepOk(after)\n          if multiparty && merged(pbs) do\n            assert lhead(pbs) == LRecv(c, p, after)\n            assert offer_step(LRecv(c, p, after), lab, c, p) == StepOk(after)\n            assert act(r, LRecv(c, p, after), ActPick(c, t, lab, p)) == StepOk(after)\n            assert merge(pbs, multiparty) == LRecv(c, p, after)\n          else\n            assert offer_step(LOffer(pbs), lab, c, p) == StepOk(after)\n            assert act(r, LOffer(pbs), ActPick(c, t, lab, p)) == StepOk(after)\n            assert merge(pbs, multiparty) == LOffer(pbs)\n          end\n        else\n          assert project(GMsg(c, t, p, k), r, multiparty) == after\n          assert merge(pbs, multiparty) == lhead(pbs)\n          assert lhead(pbs) == after\n          assert act(r, after, ActPick(c, t, lab, p)) == StepOk(after)\n        end\n      end\n    else\n      ()\n    end\n  end\n\n  doc \"Every role takes its part in a choice step.\"\n  @[lemma]\n  fn apply_pick(c : Int, bs : SessionGBranches, rs : SessionRoles, multiparty : Bool, lab : Int)\n    : {Unit | !(choice_ok(c, bs) && bystanders_merged(rs, c, bs, multiparty) && has_label(bs, lab))\n              || apply(config(GChoice(c, bs), rs, multiparty), ActPick(c, dest(bs), lab, gpay(bs, lab)))\n                 == CfgMoved(config(gcont(bs, lab), rs, multiparty))} do\n    match rs do\n      RoleEnd -> ()\n      RoleThen(r, rest) ->\n        act_pick(c, bs, multiparty, lab, r)\n        apply_pick(c, bs, rest, multiparty, lab)\n    end\n  end\n\n  doc \"Subject reduction for a choice: its step takes the configuration of the choice to that of what follows branch `lab`'s first message.\"\n  @[lemma]\n  fn step_pick(c : Int, bs : SessionGBranches, rs : SessionRoles, multiparty : Bool, lab : Int)\n    : {Unit | !(choice_ok(c, bs) && bystanders_merged(rs, c, bs, multiparty) && has_label(bs, lab) && has(rs, c) && has(rs, dest(bs)))\n              || step(config(GChoice(c, bs), rs, multiparty), ActPick(c, dest(bs), lab, gpay(bs, lab)))\n                 == CfgMoved(config(gcont(bs, lab), rs, multiparty))} do\n    let t = dest(bs)\n    present_config(GChoice(c, bs), rs, multiparty, c)\n    present_config(GChoice(c, bs), rs, multiparty, t)\n    apply_pick(c, bs, rs, multiparty, lab)\n  end\n\n  doc \"A choice's trace: the chooser's first message, carrying the label, then the branch.\"\n  @[lemma]\n  fn trace_bs_found(bs : SessionGBranches, c : Int, t : Int, lab : Int, picks : SessionPicks)\n    : {Unit | !(directed(bs, c, t) && has_label(bs, lab))\n              || trace_bs(bs, c, t, lab, picks) == ActThen(ActPick(c, t, lab, gpay(bs, lab)), trace(gcont(bs, lab), picks))} do\n    match bs do\n      GBNil -> ()\n      GBCons(l, g, rest) ->\n        if l == lab do\n          assert gbranch(bs, lab) == g\n          match g do\n            GMsg(_, _, _, _) -> ()\n            _ -> ()\n          end\n        else\n          trace_bs_found(rest, c, t, lab, picks)\n          assert gbranch(bs, lab) == gbranch(rest, lab)\n          assert gpay(bs, lab) == gpay(rest, lab)\n          assert gcont(bs, lab) == gcont(rest, lab)\n        end\n    end\n  end\n\n  doc \"The label a choice takes is one of its branches.\"\n  @[lemma]\n  fn pick_has(bs : SessionGBranches, picks : SessionPicks) : {Unit | !nonempty(bs) || has_label(bs, pick(bs, picks))} do\n    match bs do\n      GBNil -> ()\n      GBCons(_, _, _) -> ()\n    end\n  end\n\n  doc \"Every role of the configuration is done.\"\n  fn all_done(cfg : SessionCfg) : Bool do\n    match cfg do\n      CfgEnd -> true\n      CfgRole(_, l, rest) ->\n        match l do\n          LEnd -> all_done(rest)\n          _ -> false\n        end\n    end\n  end\n\n  doc \"The run took every step and every role is done.\"\n  fn finished(r : SessionCfgStep) : Bool do\n    match r do\n      CfgStuck -> false\n      CfgMoved(cfg) -> all_done(cfg)\n    end\n  end\n\n  doc \"C4's statement for one protocol: run on its own trace, the configuration of its projections takes every step and ends with every role done.\"\n  fn composes(g : SessionGlobal, rs : SessionRoles, multiparty : Bool, picks : SessionPicks) : Bool do\n    finished(run(config(g, rs, multiparty), trace(g, picks)))\n  end\n\n  doc \"The configuration of a finished protocol has every role done.\"\n  @[lemma]\n  fn end_done(rs : SessionRoles, multiparty : Bool) : {Unit | all_done(config(GEnd, rs, multiparty))} do\n    match rs do\n      RoleEnd -> ()\n      RoleThen(_, rest) -> end_done(rest, multiparty)\n    end\n  end\n\n  doc \"C4's message step: if what follows runs to the end, so does the message and what follows.\"\n  @[lemma]\n  fn compose_msg(f : Int, t : Int, p : Int, k : SessionGlobal, rs : SessionRoles, multiparty : Bool, picks : SessionPicks)\n    : {Unit | !in_fragment(GMsg(f, t, p, k), rs, multiparty)\n              || (in_fragment(k, rs, multiparty) && (!finished(run(config(k, rs, multiparty), trace(k, picks))) || finished(run(config(GMsg(f, t, p, k), rs, multiparty), trace(GMsg(f, t, p, k), picks)))))} do\n    if in_fragment(GMsg(f, t, p, k), rs, multiparty) do\n      assert f != t && has(rs, f) && has(rs, t) && in_fragment(k, rs, multiparty)\n      step_msg(f, t, p, k, rs, multiparty)\n      assert trace(GMsg(f, t, p, k), picks) == ActThen(ActMsg(f, t, p), trace(k, picks))\n      assert step(config(GMsg(f, t, p, k), rs, multiparty), ActMsg(f, t, p)) == CfgMoved(config(k, rs, multiparty))\n      assert run(config(GMsg(f, t, p, k), rs, multiparty), trace(GMsg(f, t, p, k), picks))\n             == run(config(k, rs, multiparty), trace(k, picks))\n      assert finished(run(config(GMsg(f, t, p, k), rs, multiparty), trace(GMsg(f, t, p, k), picks))) == finished(run(config(k, rs, multiparty), trace(k, picks)))\n    else\n      ()\n    end\n  end\n\n  doc \"C4's choice step: if what follows the chosen branch's first message runs to the end, so does the choice.\"\n  @[lemma]\n  fn compose_pick(c : Int, bs : SessionGBranches, rs : SessionRoles, multiparty : Bool, picks : SessionPicks)\n    : {Unit | !in_fragment(GChoice(c, bs), rs, multiparty)\n              || (in_fragment_bs(bs, rs, multiparty)\n                  && (!finished(run(config(gcont(bs, pick(bs, picks)), rs, multiparty), trace(gcont(bs, pick(bs, picks)), rest_picks(picks))))\n                      || finished(run(config(GChoice(c, bs), rs, multiparty), trace(GChoice(c, bs), picks)))))} do\n    let lab = pick(bs, picks)\n    let more = rest_picks(picks)\n    let t = dest(bs)\n    pick_has(bs, picks)\n    trace_bs_found(bs, c, t, lab, more)\n    step_pick(c, bs, rs, multiparty, lab)\n    if in_fragment(GChoice(c, bs), rs, multiparty) do\n      assert choice_ok(c, bs) && has(rs, c) && has(rs, t) && bystanders_merged(rs, c, bs, multiparty)\n      assert in_fragment_bs(bs, rs, multiparty)\n      assert nonempty(bs) && directed(bs, c, t)\n      assert has_label(bs, lab)\n      assert trace(GChoice(c, bs), picks) == trace_bs(bs, c, t, lab, more)\n      assert trace(GChoice(c, bs), picks) == ActThen(ActPick(c, t, lab, gpay(bs, lab)), trace(gcont(bs, lab), more))\n      assert step(config(GChoice(c, bs), rs, multiparty), ActPick(c, t, lab, gpay(bs, lab))) == CfgMoved(config(gcont(bs, lab), rs, multiparty))\n      assert run(config(GChoice(c, bs), rs, multiparty), trace(GChoice(c, bs), picks))\n             == run(config(gcont(bs, lab), rs, multiparty), trace(gcont(bs, lab), more))\n      assert finished(run(config(GChoice(c, bs), rs, multiparty), trace(GChoice(c, bs), picks))) == finished(run(config(gcont(bs, lab), rs, multiparty), trace(gcont(bs, lab), more)))\n    else\n      ()\n    end\n  end\n\n  doc \"C4. The projections compose back to the protocol: run on the protocol's own trace, the configuration of every role's projection takes every step and ends with every role done.\"\n  @[lemma]\n  fn projections_compose(g : SessionGlobal, rs : SessionRoles, multiparty : Bool, picks : SessionPicks)\n    : {Unit | !in_fragment(g, rs, multiparty) || finished(run(config(g, rs, multiparty), trace(g, picks)))} do\n    match g do\n      GEnd ->\n        end_done(rs, multiparty)\n        assert trace(GEnd, picks) == ActEnd\n      GVar(_) -> ()\n      GLoop(_, _) -> ()\n      GMsg(f, t, p, k) ->\n        projections_compose(k, rs, multiparty, picks)\n        compose_msg(f, t, p, k, rs, multiparty, picks)\n      GChoice(c, bs) ->\n        let lab = pick(bs, picks)\n        let more = rest_picks(picks)\n        projections_compose_bs(bs, rs, multiparty, lab, more)\n        compose_pick(c, bs, rs, multiparty, picks)\n    end\n  end\n\n  doc \"C4 for what follows branch `lab`'s first message.\"\n  @[lemma]\n  fn projections_compose_bs(bs : SessionGBranches, rs : SessionRoles, multiparty : Bool, lab : Int, picks : SessionPicks)\n    : {Unit | !in_fragment_bs(bs, rs, multiparty) || finished(run(config(gcont(bs, lab), rs, multiparty), trace(gcont(bs, lab), picks)))} do\n    match bs do\n      GBNil ->\n        end_done(rs, multiparty)\n        assert gcont(bs, lab) == GEnd\n        assert trace(GEnd, picks) == ActEnd\n      GBCons(l, g, rest) ->\n        match g do\n          GMsg(_, _, _, k) ->\n            assert !in_fragment_bs(bs, rs, multiparty) || (in_fragment(g, rs, multiparty) && in_fragment_bs(rest, rs, multiparty))\n            assert !in_fragment(g, rs, multiparty) || in_fragment(k, rs, multiparty)\n            if l == lab do\n              assert gcont(bs, lab) == k\n              projections_compose(k, rs, multiparty, picks)\n            else\n              assert gcont(bs, lab) == gcont(rest, lab)\n              projections_compose_bs(rest, rs, multiparty, lab, picks)\n            end\n          _ ->\n            assert !in_fragment_bs(bs, rs, multiparty) || in_fragment_bs(rest, rs, multiparty)\n            if l == lab do\n              end_done(rs, multiparty)\n              assert gcont(bs, lab) == GEnd\n              assert trace(GEnd, picks) == ActEnd\n            else\n              assert gcont(bs, lab) == gcont(rest, lab)\n              projections_compose_bs(rest, rs, multiparty, lab, picks)\n            end\n        end\n    end\n  end\n\n  doc \"The first step of the protocol's trace (a no-op message when there is none).\"\n  fn first_act(g : SessionGlobal, picks : SessionPicks) : SessionAct do\n    match trace(g, picks) do\n      ActEnd -> ActMsg(0, 0, 0)\n      ActThen(a, _) -> a\n    end\n  end\n\n  doc \"C5. Deadlock freedom (synchronous, the fragment): while the protocol has a next step, the configuration of the projections can take it.\"\n  @[lemma]\n  fn progress(g : SessionGlobal, rs : SessionRoles, multiparty : Bool, picks : SessionPicks)\n    : {Unit | !in_fragment(g, rs, multiparty) || trace(g, picks) == ActEnd\n              || step(config(g, rs, multiparty), first_act(g, picks)) != CfgStuck} do\n    match g do\n      GEnd -> ()\n      GVar(_) -> ()\n      GLoop(_, _) -> ()\n      GMsg(f, t, p, k) -> if f != t do step_msg(f, t, p, k, rs, multiparty) else () end\n      GChoice(c, bs) ->\n        let lab = pick(bs, picks)\n        let t = dest(bs)\n        let more = rest_picks(picks)\n        pick_has(bs, picks)\n        trace_bs_found(bs, c, t, lab, more)\n        step_pick(c, bs, rs, multiparty, lab)\n    end\n  end\n\n  -- \u2500\u2500 C3: pairwise duality \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"Duality keeps branches alike.\"\n  @[lemma]\n  fn all_same_dual(rest : SessionLBranches, first : SessionLocal)\n    : {Unit | all_same(dual_bs(rest), dual(first)) == all_same(rest, first)} do\n    match rest do\n      LBNil -> ()\n      LBCons(_, k, more) ->\n        same_eq(dual(k), dual(first))\n        same_eq(k, first)\n        dual_dual(k)\n        dual_dual(first)\n        all_same_dual(more, first)\n    end\n  end\n\n  doc \"Duality keeps a choice merged.\"\n  @[lemma]\n  fn merged_dual(rb : SessionLBranches) : {Unit | merged(dual_bs(rb)) == merged(rb)} do\n    match rb do\n      LBNil -> ()\n      LBCons(_, first, rest) -> all_same_dual(rest, first)\n    end\n  end\n\n  doc \"The first branch of the dual is the dual of the first branch.\"\n  @[lemma]\n  fn lhead_dual(rb : SessionLBranches) : {Unit | lhead(dual_bs(rb)) == dual(lhead(rb))} do\n    match rb do\n      LBNil -> ()\n      LBCons(_, _, _) -> ()\n    end\n  end\n\n  doc \"A choice and an offer over dual branches are dual.\"\n  @[lemma]\n  fn collapse_dual(rb : SessionLBranches)\n    : {Unit | collapse(dual_bs(rb), true) == dual(collapse(rb, false))\n              && collapse(dual_bs(rb), false) == dual(collapse(rb, true))} do\n    match rb do\n      LBNil -> ()\n      LBCons(_, first, rest) -> all_same_dual(rest, first)\n    end\n  end\n\n  doc \"Merged branches collapse to their first.\"\n  @[lemma]\n  fn collapse_merged(rb : SessionLBranches, as_choice : Bool)\n    : {Unit | !merged(rb) || collapse(rb, as_choice) == lhead(rb)} do\n    match rb do\n      LBNil -> ()\n      LBCons(_, _, _) -> ()\n    end\n  end\n\n  doc \"Restricting keeps branches alike.\"\n  @[lemma]\n  fn restrict_all_same(rest : SessionLBranches, first : SessionLocal, x : Int)\n    : {Unit | !all_same(rest, first) || all_same(restrict_bs(rest, x), restrict(first, x))} do\n    match rest do\n      LBNil -> ()\n      LBCons(_, k, more) ->\n        same_eq(k, first)\n        same_eq(restrict(k, x), restrict(first, x))\n        restrict_all_same(more, first, x)\n    end\n  end\n\n  doc \"Restricting keeps a choice merged, and commutes with taking its first branch.\"\n  @[lemma]\n  fn merged_restrict(pbs : SessionLBranches, x : Int)\n    : {Unit | !merged(pbs) || (merged(restrict_bs(pbs, x)) && lhead(restrict_bs(pbs, x)) == restrict(lhead(pbs), x))} do\n    match pbs do\n      LBNil -> ()\n      LBCons(_, first, rest) -> restrict_all_same(rest, first, x)\n    end\n  end\n\n  doc \"A role's part of a choice, restricted to a peer: its branches restricted and collapsed, a choice for the chooser and an offer for anyone else.\"\n  @[lemma]\n  fn restrict_choice(c : Int, bs : SessionGBranches, r : Int, x : Int, multiparty : Bool)\n    : {Unit | restrict(project(GChoice(c, bs), r, multiparty), x)\n              == collapse(restrict_bs(project_bs(bs, r, multiparty), x), r == c)} do\n    let pbs = project_bs(bs, r, multiparty)\n    let rb = restrict_bs(pbs, x)\n    if r == c do\n      assert project(GChoice(c, bs), r, multiparty) == LChoose(pbs)\n      assert restrict(LChoose(pbs), x) == collapse(rb, true)\n    else\n      assert project(GChoice(c, bs), r, multiparty) == merge(pbs, multiparty)\n      merge_cases(pbs, multiparty)\n      merged_restrict(pbs, x)\n      collapse_merged(rb, false)\n      assert restrict(LOffer(pbs), x) == collapse(rb, false)\n    end\n  end\n\n  doc \"A role of `rs` takes part in a choice of the fragment correctly.\"\n  @[lemma]\n  fn role_ok_has(rs : SessionRoles, c : Int, bs : SessionGBranches, multiparty : Bool, r : Int)\n    : {Unit | !(bystanders_merged(rs, c, bs, multiparty) && has(rs, r)) || role_ok(c, bs, r, multiparty)} do\n    match rs do\n      RoleEnd -> ()\n      RoleThen(_, rest) -> role_ok_has(rest, c, bs, multiparty, r)\n    end\n  end\n\n  doc \"C3 at a choice: with each branch's restrictions dual, the choice's are.\"\n  @[lemma]\n  fn pairwise_choice(c : Int, bs : SessionGBranches, rs : SessionRoles, multiparty : Bool, p : Int, q : {Int | _ != p})\n    : {Unit | !(in_fragment(GChoice(c, bs), rs, multiparty) && has(rs, p) && has(rs, q))\n              || restrict_bs(project_bs(bs, p, multiparty), q) != dual_bs(restrict_bs(project_bs(bs, q, multiparty), p))\n              || restrict(project(GChoice(c, bs), p, multiparty), q) == dual(restrict(project(GChoice(c, bs), q, multiparty), p))} do\n    let pbp = project_bs(bs, p, multiparty)\n    let pbq = project_bs(bs, q, multiparty)\n    let rbp = restrict_bs(pbp, q)\n    let rbq = restrict_bs(pbq, p)\n    restrict_choice(c, bs, p, q, multiparty)\n    restrict_choice(c, bs, q, p, multiparty)\n    collapse_dual(rbq)\n    role_ok_has(rs, c, bs, multiparty, p)\n    role_ok_has(rs, c, bs, multiparty, q)\n    merged_restrict(pbp, q)\n    merged_restrict(pbq, p)\n    merged_dual(rbq)\n    lhead_dual(rbq)\n    collapse_merged(rbq, false)\n    collapse_merged(dual_bs(rbq), false)\n  end\n\n  doc \"C3. Pairwise duality (the fragment): for two roles of a protocol, what one does with the other is the dual of what the other does with it.\"\n  @[lemma]\n  fn pairwise(g : SessionGlobal, rs : SessionRoles, multiparty : Bool, p : Int, q : {Int | _ != p})\n    : {Unit | !(in_fragment(g, rs, multiparty) && has(rs, p) && has(rs, q))\n              || restrict(project(g, p, multiparty), q) == dual(restrict(project(g, q, multiparty), p))} do\n    match g do\n      GEnd -> ()\n      GVar(_) -> ()\n      GLoop(_, _) -> ()\n      GMsg(f, t, pay, k) ->\n        pairwise(k, rs, multiparty, p, q)\n        assert !in_fragment(GMsg(f, t, pay, k), rs, multiparty) || in_fragment(k, rs, multiparty)\n        let pk = project(k, p, multiparty)\n        let qk = project(k, q, multiparty)\n        let rp = restrict(pk, q)\n        let rq = restrict(qk, p)\n        if p == f do\n          assert project(GMsg(f, t, pay, k), p, multiparty) == LSend(t, pay, pk)\n          if q == t do\n            assert project(GMsg(f, t, pay, k), q, multiparty) == LRecv(f, pay, qk)\n            assert restrict(LSend(t, pay, pk), q) == LSend(0, pay, rp)\n            assert restrict(LRecv(f, pay, qk), p) == LRecv(0, pay, rq)\n            assert dual(LRecv(0, pay, rq)) == LSend(0, pay, dual(rq))\n          else\n            assert project(GMsg(f, t, pay, k), q, multiparty) == qk\n            assert restrict(LSend(t, pay, pk), q) == rp\n          end\n        else if p == t do\n          assert project(GMsg(f, t, pay, k), p, multiparty) == LRecv(f, pay, pk)\n          if q == f do\n            assert project(GMsg(f, t, pay, k), q, multiparty) == LSend(t, pay, qk)\n            assert restrict(LRecv(f, pay, pk), q) == LRecv(0, pay, rp)\n            assert restrict(LSend(t, pay, qk), p) == LSend(0, pay, rq)\n            assert dual(LSend(0, pay, rq)) == LRecv(0, pay, dual(rq))\n          else\n            assert project(GMsg(f, t, pay, k), q, multiparty) == qk\n            assert restrict(LRecv(f, pay, pk), q) == rp\n          end\n        else\n          assert project(GMsg(f, t, pay, k), p, multiparty) == pk\n          if q == f do\n            assert project(GMsg(f, t, pay, k), q, multiparty) == LSend(t, pay, qk)\n            assert restrict(LSend(t, pay, qk), p) == rq\n          else if q == t do\n            assert project(GMsg(f, t, pay, k), q, multiparty) == LRecv(f, pay, qk)\n            assert restrict(LRecv(f, pay, qk), p) == rq\n          else\n            assert project(GMsg(f, t, pay, k), q, multiparty) == qk\n          end end\n        end end\n      GChoice(c, bs) ->\n        assert !in_fragment(GChoice(c, bs), rs, multiparty) || in_fragment_bs(bs, rs, multiparty)\n        pairwise_bs(bs, rs, multiparty, p, q)\n        pairwise_choice(c, bs, rs, multiparty, p, q)\n    end\n  end\n\n  doc \"C3 on every branch.\"\n  @[lemma]\n  fn pairwise_bs(bs : SessionGBranches, rs : SessionRoles, multiparty : Bool, p : Int, q : {Int | _ != p})\n    : {Unit | !(in_fragment_bs(bs, rs, multiparty) && has(rs, p) && has(rs, q))\n              || restrict_bs(project_bs(bs, p, multiparty), q) == dual_bs(restrict_bs(project_bs(bs, q, multiparty), p))} do\n    match bs do\n      GBNil -> ()\n      GBCons(_, g, rest) ->\n        assert !in_fragment_bs(bs, rs, multiparty) || (in_fragment(g, rs, multiparty) && in_fragment_bs(rest, rs, multiparty))\n        pairwise(g, rs, multiparty, p, q)\n        pairwise_bs(rest, rs, multiparty, p, q)\n    end\n  end\nend\n";
